const $=id=>document.getElementById(id), uid=()=>crypto.randomUUID();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v/100);
const date=v=>new Date(v+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const icons={hoje:'<path d="M3 10 10 3l7 7v8H3zM7 18v-6h6v6"/>',agenda:'<rect x="3" y="5" width="14" height="13" rx="2"/><path d="M6 2v5M14 2v5M3 10h14"/>',pacientes:'<circle cx="8" cy="7" r="3"/><path d="M2 18c0-7 12-7 12 0M15 4a3 3 0 0 1 0 6M16 12c2 1 2 3 2 5"/>',financeiro:'<rect x="2" y="5" width="16" height="12" rx="2"/><path d="M2 9h16M5 13h3"/>',ajustes:'<circle cx="10" cy="10" r="3"/><path d="M10 1v3M10 16v3M1 10h3M16 10h3M4 4l2 2M14 14l2 2M4 16l2-2M14 6l2-2"/>',plus:'<path d="M10 3v14M3 10h14"/>',arrow:'<path d="M3 10h14M12 5l5 5-5 5"/>',photo:'<rect x="2" y="3" width="16" height="14" rx="2"/><circle cx="7" cy="8" r="2"/><path d="m3 16 5-5 3 3 3-6 4 8"/>',check:'<path d="m3 10 5 5L18 4"/>'};
function serviceTone(service){const normalized=String(service).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();return /\bavalia/.test(normalized)?'avaliacao':/\bretorno\b/.test(normalized)?'retorno':'procedimento';}
function serviceBadge(service){const tone=serviceTone(service),label={avaliacao:'Avaliação',procedimento:'Atendimento',retorno:'Retorno'}[tone];return `<span class="service-tone" data-service-tone="${tone}"><span class="service-type">${label}</span><span>${esc(service)}</span></span>`;}
const icon=n=>`<svg class="icon" viewBox="0 0 20 20" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
let state,route='hoje',patientId,visitId,tab='consultas',photoId,selectedId=null,pending=null,dirty=false,busy=false,zoom=1,tool='ponto',agendaDate=dateKey();
let toastTimer,dialogSubmit=null,objectUrls=new Map(),renderSeq=0,drag=null,acceptedHash=location.hash,importing=false,editGeneration=0;
const comparisonSelections=new Map();
let mapFitObserver=null,integrationHandle=null;
function fitMapPlane(resetScroll=false){
  const stage=$('photo-stage'),plane=$('photo-plane'),image=$('map-photo');
  if(!stage||!plane||!image?.complete)return;
  const fit=fittedPhotoSize(stage.clientWidth,stage.clientHeight,image.naturalWidth,image.naturalHeight,zoom);
  if(!fit)return;
  plane.style.width=fit.width+'px';
  if($('zoom-label'))$('zoom-label').textContent=Math.round(fit.zoom*100)+'%';
  if(resetScroll){stage.scrollLeft=0;stage.scrollTop=0;}
}
function fitLoadedMapPhoto(image,url,seq){
  mapFitObserver?.disconnect();mapFitObserver=null;
  const stage=$('photo-stage');
  const current=()=>seq===renderSeq&&image.isConnected;
  image.addEventListener('load',()=>{if(current())fitMapPlane(true);},{once:true});
  image.src=url;
  if(image.complete&&image.naturalWidth&&current())fitMapPlane(true);
  if(typeof ResizeObserver!=='undefined'){
    const observer=new ResizeObserver(()=>{if(current())fitMapPlane();else{observer.disconnect();if(mapFitObserver===observer)mapFitObserver=null;}});
    mapFitObserver=observer;observer.observe(stage);
  }
}
function toast(message,error=false){$('toast').textContent=message;$('toast').className='toast visible'+(error?' failure':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').className='toast',4500);}
const patient=id=>state.patients.find(p=>p.id===id);
const visit=()=>state.visits.find(v=>v.id===visitId&&v.patientId===patientId);
const photo=()=>visit()?.photos.find(p=>p.id===photoId);
const map=()=>visit()?.maps[photoId]||{version:0,points:[],history:[]};
function clean(){if(integrationHandle?.isBusy()){toast('Aguarde a operação da área privada terminar.');return false;}if(!dirty&&!pending&&!integrationHandle?.isDirty()&&!document.querySelector('form[data-unsaved]'))return true;if(!confirm('Há uma marcação ou edição ainda não salva. Descartar essa edição?'))return false;dirty=false;pending=null;document.querySelectorAll('form[data-unsaved]').forEach(f=>delete f.dataset.unsaved);document.querySelectorAll('dialog[open]').forEach(d=>d.close());return true;}
function navigate(hash){if(busy||importing){toast('Aguarde o registro em andamento.');return;}if(!clean())return;if(location.hash==='#'+hash)void setHash();else location.hash=hash;}
function lockInterface(value){$('content').inert=value;$('dialog-form').inert=value;$('close-dialog').disabled=value;$('cancel-dialog').disabled=value;}
async function persist(update,blob){if(busy)throw Error('Aguarde o registro em andamento.');busy=true;lockInterface(true);try{state=await commit(state.revision,update,blob);return state;}finally{busy=false;lockInterface(false);}}
async function setHash(){if(location.hash!==acceptedHash&&((busy||importing)||!clean())){history.replaceState(null,'',acceptedHash||'#hoje');return;}if(busy||importing)return;acceptedHash=location.hash;busy=true;lockInterface(true);try{state=await load();const parts=acceptedHash.replace(/^#/,'').split('/');route=parts[0]||'hoje';patientId=parts[1];visitId=parts[2];tab=parts[3]||'consultas';selectedId=null;pending=null;dirty=false;zoom=1;await render();}finally{busy=false;lockInterface(false);drawMap();}}
function heading(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`;}
function badge(status){return `<span class="badge ${['confirmado','concluido'].includes(status)?'green':'gold'}">${esc({agendado:'A confirmar',confirmado:'Confirmado',concluido:'Atendido',cancelado:'Cancelado',rascunho:'Rascunho local'}[status]||status)}</span>`;}
function metrics(){const s=financialSummary(state);return `<div class="metric-grid"><article class="metric featured"><div class="metric-label">Recebido no piloto ${icon('financeiro')}</div><strong class="metric-number amount">${money(s.received)}</strong><small>Valores fictícios já registrados</small></article><article class="metric"><div class="metric-label">A receber ${icon('financeiro')}</div><strong class="metric-number amount">${money(s.outstanding)}</strong><small>Saldo dos exemplos de cobrança</small></article><article class="metric"><div class="metric-label">Atendimentos de hoje ${icon('agenda')}</div><strong class="metric-number">${state.appointments.filter(a=>a.date===dateKey()&&a.status!=='cancelado').length.toString().padStart(2,'0')}</strong><small>Agenda de demonstração</small></article></div>`;}
function appointmentRow(a){return `<div class="appointment-row" data-service-tone="${serviceTone(a.service)}"><div class="time">${esc(a.time)}<small>${a.duration} min</small></div><div><div class="appointment-person">${esc(patient(a.patientId)?.name)}</div><div class="appointment-service">${serviceBadge(a.service)}</div></div><div class="row-actions">${badge(a.status)}<button class="subtle" data-action="attend" data-id="${a.id}">Abrir ${icon('arrow')}</button></div></div>`;}
function todayPage(){return renderHome(state);}
function requestCards(){const pending=(state.requests||[]).filter(r=>r.status==='pendente');return pending.length?`<section class="card" style="margin-bottom:22px"><header class="card-header"><div><h2>Solicitações pelo site <span class="badge gold">${pending.length}</span></h2><p>Preferências recebidas. Ainda sem horário reservado.</p></div></header>${pending.map(r=>`<article class="visit-item"><div><h3>${esc(r.name)}</h3><p>${esc(r.phone)} · ${date(r.date)} / ${esc(r.period)} · ${esc(r.interest)}</p></div><button class="secondary" data-action="schedule-request" data-id="${r.id}">Preparar agendamento →</button></article>`).join('')}</section>`:'';}
function agendaPage(){const items=state.appointments.filter(a=>a.date===agendaDate).sort((a,b)=>a.time.localeCompare(b.time));return heading('AGENDA','Agenda','Um único horário, uma paciente e um próximo passo.',`<button class="primary" data-action="new-appointment">${icon('plus')} Agendar</button>`)+requestCards()+`<div class="search-row"><label for="agenda-date">Dia</label><input id="agenda-date" type="date" value="${agendaDate}" style="width:180px"><button class="secondary" data-action="today">Hoje</button></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Horário</th><th>Paciente / atendimento</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${items.map(a=>`<tr data-service-tone="${serviceTone(a.service)}"><td>${a.time}<br><small>${a.duration} minutos</small></td><td><strong>${esc(patient(a.patientId)?.name)}</strong><small>${serviceBadge(a.service)}</small></td><td>${badge(a.status)}</td><td><div class="toolbar"><button class="subtle" data-action="attend" data-id="${a.id}" ${a.status==='cancelado'?'disabled':''}>Abrir</button><button class="subtle" data-action="edit-appointment" data-id="${a.id}">Editar</button></div></td></tr>`).join('')}</tbody></table></div>${items.length?'':'<div class="empty">Nenhum atendimento neste dia.</div>'}</section>`;}
function patientsPage(){return heading('PRONTUÁRIOS','Prontuários','Histórico e informações das suas pacientes.',`<button class="primary" data-action="new-patient">${icon('plus')} Nova paciente</button>`)+`<section class="card patient-list-card"><div class="search-row"><input class="search-input" id="patient-search" type="search" placeholder="Buscar por nome, CPF, telefone ou e-mail" aria-label="Buscar paciente"><span class="patient-total">${state.patients.length} paciente(s) no piloto</span></div><div class="patient-list-head" aria-hidden="true"><span>Paciente</span><span>Contato</span><span class="date-column">Última consulta</span><span>Histórico</span><span></span></div><div class="patient-grid" id="patient-grid">${patientCards('')}</div></section>`;}
function initials(name){return name.split(' ').filter(Boolean).slice(0,2).map(n=>n[0]).join('');}
function patientCards(query){return state.patients.filter(p=>patientMatches(p,query)).map(p=>{const visits=state.visits.filter(v=>v.patientId===p.id).sort((a,b)=>b.date.localeCompare(a.date));return `<a class="patient-row" href="#paciente/${p.id}" aria-label="Abrir prontuário de ${esc(p.name)}"><span class="patient-row-person"><span class="avatar">${esc(initials(p.name))}</span><span><strong>${esc(p.name)}</strong><small>Cadastro de demonstração</small></span></span><span class="patient-row-contact">${esc(p.phone||'Sem telefone informado')}</span><span class="patient-row-date">${visits[0]?date(visits[0].date):'Sem consultas'}</span><span class="patient-history" aria-label="${visits.length} consultas">${visits.length}</span>${icon('arrow')}</a>`;}).join('')||'<p class="empty">Nenhuma paciente encontrada.</p>';}
function patientPage(){const p=patient(patientId);if(!p)return '<div class="empty">Paciente não encontrada.</div>';const v=visit();const visits=state.visits.filter(v=>v.patientId===p.id).sort((a,b)=>b.date.localeCompare(a.date));return `<a class="back" href="#pacientes">← Todas as pacientes</a><div class="patient-head"><span class="avatar">${esc(initials(p.name))}</span><div><p class="eyebrow">PRONTUÁRIO DE DEMONSTRAÇÃO</p><h1>${esc(p.name)}</h1><p class="subtitle">${p.phone?esc(p.phone):'Cadastro do piloto local'}</p></div><div class="toolbar"><button class="secondary" data-action="edit-patient" data-id="${p.id}">Editar cadastro</button><button class="primary" data-action="new-visit">${icon('plus')} Nova consulta</button></div></div>`+(v?`<div class="visit-info" data-service-tone="${serviceTone(v.service)}"><div><h2>${esc(v.service)}</h2><p>${date(v.date)} · Registro fictício para teste de usabilidade</p></div>${badge(v.status)}</div><nav class="tabs" aria-label="Áreas da consulta">${[['registro','Registro'],['mapa','Mapa facial'],['fotos','Fotos e comparação'],['documentos','Documentos']].map(([id,label])=>`<a class="tab ${tab===id?'active':''}" href="#paciente/${p.id}/${v.id}/${id}">${label}</a>`).join('')}<a class="tab" href="#paciente/${p.id}">Todas as consultas</a></nav>${tab==='mapa'?mapPage(v):tab==='fotos'?photosPage(v):tab==='documentos'?renderDocumentsPage(state,{visitId:v.id}):recordPage(v)+renderVisitOperations(state,v.id)}`:`<section class="card"><header class="card-header"><div><h2>Histórico de consultas</h2><p>Abra uma consulta para ver o registro e suas fotografias.</p></div></header>${visits.map(v=>`<article class="visit-item"><div><h3>${esc(v.service)}</h3><p>${date(v.date)} · ${v.photos.length} fotografia(s)</p></div><div class="toolbar">${badge(v.status)}<a class="secondary" href="#paciente/${p.id}/${v.id}/registro">Abrir consulta →</a></div></article>`).join('')||'<div class="empty">Cadastre a primeira consulta de teste.</div>'}</section><div class="note-box">Anamneses, termos e assinaturas de demonstração estão dentro de cada consulta. Documentos operacionais ficam na área de conexão privada.</div>`);}
function recordPage(v){return `<div class="record-grid"><section class="card"><header class="card-header"><div><h2>Registro do atendimento</h2><p>As informações ficam vinculadas a esta consulta.</p></div></header><form class="card-body" id="record-form"><div class="field"><label for="visit-notes">Observações do atendimento de teste</label><textarea id="visit-notes" rows="9" maxlength="4000">${esc(v.notes)}</textarea></div><p class="small-label">Use informações fictícias. Ao concluir, o registro fica bloqueado; correções posteriores são feitas por adendo.</p><button class="primary">Salvar rascunho local</button><span class="saved-at" id="record-saved"></span></form></section><section class="card"><header class="card-header"><h2>Seu próximo passo</h2></header><div class="card-body"><div class="readiness"><span class="mark">1</span> Registrar o atendimento</div><a class="readiness" href="#paciente/${patientId}/${v.id}/mapa"><span class="mark">2</span> Abrir a foto e fazer as marcações →</a><a class="readiness" href="#paciente/${patientId}/${v.id}/fotos"><span class="mark">3</span> Organizar as fotos e a comparação →</a><div class="note-box">Abra Documentos para preencher os modelos e testar a assinatura. A assinatura de demonstração não tem validade clínica.</div></div></section></div>`;}
function fileControl(){return `<label class="secondary file-label">${icon('photo')} Adicionar foto<input class="hidden-file" type="file" id="photo-upload" accept="image/jpeg,image/png,image/webp" aria-label="Adicionar foto à consulta"></label>`;}
function mapPage(v){if(!v.photos.length)return `<div class="card card-body"><h2>Comece pela fotografia</h2><p class="subtitle">A marcação fica vinculada à foto original e a esta consulta.</p><div style="margin-top:20px">${fileControl()}</div><p class="file-info">Neste piloto, utilize imagens de teste. JPEG, PNG ou WebP, até 8 MB.</p></div>`;
  if(!v.photos.some(p=>p.id===photoId))photoId=v.photos[0].id;
  const doc=map();return `<div class="photo-picker"><select id="photo-select" aria-label="Foto da consulta">${v.photos.map(p=>`<option value="${p.id}" ${p.id===photoId?'selected':''}>${esc(p.label)}</option>`).join('')}</select>${fileControl()}<span class="small-label">Original preservado · marcações em camada separada</span></div><div class="map-layout"><section class="map-card"><div class="map-toolbar"><div class="segmented" aria-label="Ferramenta de marcação">${[['ponto','Ponto'],['linha','Linha'],['leque','Leque']].map(([id,label])=>`<button class="segment ${tool===id?'active':''}" data-action="tool" data-id="${id}" aria-pressed="${tool===id}">${label}</button>`).join('')}</div><div class="toolbar"><button class="icon-button" data-action="zoom-out" aria-label="Diminuir zoom">−</button><span id="zoom-label" class="small-label">100%</span><button class="icon-button" data-action="zoom-in" aria-label="Aumentar zoom">+</button></div></div><div class="map-status" id="map-instruction">${tool==='ponto'?'Toque na foto para criar um ponto.':'Toque no início e no fim da marcação.'} Selecione um número para editar.</div><div class="photo-stage" id="photo-stage"><div class="photo-plane" id="photo-plane"><img id="map-photo" alt="Fotografia de teste da consulta; marcações manuais sobre a imagem" draggable="false"><svg class="map-svg" id="map-svg" viewBox="0 0 1000 1000" preserveAspectRatio="none" aria-hidden="true"></svg><div id="map-markers"></div></div></div><div class="map-footer"><span>Registro manual · versão local <span id="map-version">${doc.version}</span></span><div class="toolbar"><button class="subtle" data-action="toggle-markers">Ocultar marcações</button><button class="subtle" data-action="export-map">Exportar imagem</button></div></div></section><aside class="map-side"><section class="card"><header class="card-header"><h2 id="point-title">Nova marcação</h2><span class="small-label" id="point-state">Toque na fotografia</span></header><form class="card-body" id="point-form"><div class="field"><label for="point-region">Região / identificação</label><input id="point-region" maxlength="100" required placeholder="Nome que você deseja registrar"></div><div class="field"><label for="point-product">Produto</label><input id="point-product" maxlength="120" placeholder="Informe o produto utilizado"></div><div class="field-grid"><div class="field"><label for="point-quantity">Quantidade</label><input id="point-quantity" inputmode="decimal" placeholder="Opcional"></div><div class="field"><label for="point-unit">Unidade</label><select id="point-unit"><option>sem quantidade</option><option>mL</option><option>U</option><option>mg</option></select></div></div><div class="field"><label for="point-lot">Lote</label><input id="point-lot" maxlength="80" placeholder="Opcional no rascunho"></div><div class="field"><label for="point-notes">Observação</label><textarea id="point-notes" maxlength="2000" placeholder="Anotação manual da profissional"></textarea></div><p id="point-error" role="alert" class="error"></p><button class="primary" id="save-point" disabled>Salvar marcação local</button><div class="toolbar" style="justify-content:space-between;margin-top:6px"><button class="subtle" type="button" data-action="cancel-point">Cancelar edição</button><button class="subtle" type="button" id="delete-point" data-action="delete-point" hidden>Excluir ponto</button></div></form></section><section class="card" style="margin-top:16px"><header class="card-header"><h2>Legenda <span id="point-count" class="badge">${doc.points.length}</span></h2><button class="subtle" data-action="undo-map" ${doc.history.length?'':'disabled'}>Desfazer</button></header><div id="point-list"></div><div class="legend-total" id="quantity-totals"></div></section><p class="map-tip" style="margin-top:14px">Arraste um número para ajustar a posição. As quantidades são informadas por você; o sistema não recomenda locais, produtos ou doses.</p></aside></div>`;}
function photosPage(v){return `<div class="page-heading"><p class="subtitle">Fotografias da mesma consulta. Cada foto tem sua própria camada de marcação.</p>${fileControl()}</div><div class="photos-grid">${v.photos.map(p=>`<article class="card photo-thumb"><img data-photo-src="${p.id}" alt="${esc(p.label)}"><h3>${esc(p.label)}</h3><p>${p.phase==='depois'?'Depois':p.phase==='antes'?'Antes':'Registro'} · ${p.width} × ${p.height} px</p><div class="toolbar"><button class="subtle" data-action="open-photo-map" data-id="${p.id}">Marcar nesta foto →</button><button class="subtle" data-action="photo-phase" data-id="${p.id}">Classificar</button></div></article>`).join('')||'<p class="empty">Nenhuma foto nesta consulta.</p>'}</div><section class="card" style="margin-top:24px"><header class="card-header"><div><h2>Antes e depois</h2><p>Selecione fotografias desta paciente, inclusive entre consultas diferentes.</p></div></header><div class="card-body" id="comparison-panel"></div></section><div class="note-box">Adicionar uma foto não autoriza sua divulgação. O piloto guarda a imagem somente neste navegador e não conecta ao prontuário real.</div>`;}
async function comparisonSource(item,original=false){if(!original)return photoUrl(item.photo);const stored=await getPhoto(item.photo.id);if(stored?.original)return stored.original;if(item.photo.src)return item.photo.src;throw Error('O arquivo original não está disponível neste navegador.');}
function financePage(){const s=financialSummary(state);return heading('FINANCEIRO','Financeiro','Recebimentos e saldos, sem misturar promessa com dinheiro recebido.',`<button class="primary" data-action="new-bill">${icon('plus')} Nova cobrança</button>`)+metrics()+`<section class="card"><header class="card-header"><div><h2>Cobranças do piloto</h2><p>Recebimentos parciais são permitidos. Saldo zerado não aceita nova baixa.</p></div></header><div class="table-wrap"><table><thead><tr><th>Paciente / descrição</th><th>Total</th><th>Recebido</th><th>Saldo</th><th></th></tr></thead><tbody>${state.bills.map(b=>{const bal=billBalance(b,state.payments);return `<tr><td><strong>${esc(patient(b.patientId)?.name)}</strong><small>${esc(b.description)}</small></td><td>${money(b.total)}</td><td>${money(b.total-bal)}</td><td>${money(bal)}</td><td><button class="subtle" data-action="receive" data-id="${b.id}" ${bal===0?'disabled':''}>${bal===0?'Recebido':'Registrar recebimento'}</button></td></tr>`;}).join('')}</tbody></table></div></section><div class="dashboard-grid" style="margin-top:22px"><section class="card"><header class="card-header"><h2>Livro de recebimentos de teste</h2></header><div class="table-wrap"><table><thead><tr><th>Data</th><th>Forma</th><th>Valor</th></tr></thead><tbody>${state.payments.map(p=>`<tr><td>${date(p.date)}</td><td>${esc(p.method)}</td><td>${money(p.amount)}</td></tr>`).join('')}</tbody></table></div></section><section class="card card-body"><p class="eyebrow">SIMULAÇÃO DE RESULTADO</p><h2>Contribuição estimada</h2><strong class="metric-number">${money(s.contribution)}</strong><p class="details-text">Total cobrado ${money(s.billed)} menos custos variáveis informados ${money(s.variableCosts)}. Não representa lucro líquido: impostos, taxas e custos fixos ainda não foram informados.</p></section></div>`;}
function settingsPage(){return heading('CONTA E SUPORTE','Configuração e recuperação','Seu ambiente de testes e as opções para proteger seus exemplos.')+`<div class="record-grid"><section class="card card-body"><h2>Seu espaço de trabalho</h2><p class="details-text">Cadastro, agenda, documentos, fotos, mapas, estoque, orçamentos e financeiro estão vinculados neste navegador. Exporte cópias completas para proteger os testes.</p><div class="toolbar"><a class="secondary" href="https://anamariajacob.com.br/" target="_blank" rel="noopener">Abrir site da Ana</a><a class="secondary" href="#documentos">Modelos de documentos</a></div></section><section class="card card-body"><h2>Base real da clínica</h2><p class="details-text">Este aplicativo está em testes e salva somente neste navegador. O painel atual da clínica continua disponível com seu acesso individual.</p><a class="primary" href="https://anamariajacob.com.br/painel/" target="_blank" rel="noopener noreferrer">Abrir painel da clínica →</a><p class="small-label">O mapa facial ampliado ainda precisa de validação do contrato no servidor antes do uso operacional.</p></section></div>`+renderRecoveryPage(state);}
async function photoUrl(p){if(objectUrls.has(p.id))return objectUrls.get(p.id);const blob=await getPhoto(p.id);if(blob?.preview){const url=URL.createObjectURL(blob.preview);objectUrls.set(p.id,url);return url;}if(p.src)return p.src;throw Error('A foto não está disponível neste navegador.');}
async function render(){
 if(!state)return;integrationHandle?.dispose();integrationHandle=null;const seq=++renderSeq;
 const active=route==='paciente'||route==='documento'?'pacientes':route==='documentos'?'clinica':route==='integracao'?'ajustes':route;
 $('crumb').textContent=areas.find(a=>a.id===active)?.label||'Início';
 $('nav').innerHTML=areas.map(({id,label,icon:areaIcon})=>`<a class="nav-item ${active===id?'active':''} ${id==='clinica'?'section-start':''}" href="#${id}" ${active===id?'aria-current="page"':''}>${icon(areaIcon)}<span>${label}</span></a>`).join('');
 $('area-switch').innerHTML=areas.map(({id,label})=>`<option value="${id}" ${active===id?'selected':''}>${label}</option>`).join('');
 const documentVisit=route==='documento'?state.documentResponses.find(d=>d.id===patientId)?.visitId:undefined;
 const pages={hoje:todayPage,agenda:()=>agendaPage()+renderAgendaSupport(state,{date:agendaDate}),pacientes:patientsPage,paciente:patientPage,financeiro:()=>renderFinancePage(state),ajustes:settingsPage,orcamentos:()=>renderOperationsPage('orcamentos',state),catalogo:()=>renderOperationsPage('catalogo',state),clinica:()=>renderClinicPage(state)+'<div class="toolbar"><a class="secondary" href="#documentos">Anamneses e termos →</a></div>',documentos:()=>renderDocumentsPage(state),documento:()=>documentVisit?renderDocumentsPage(state,{visitId:documentVisit}):'<p class="empty">Documento não encontrado neste navegador.</p>',integracao:renderIntegrationPage};
 $('content').innerHTML='<div id="page-body">'+(pages[route]||todayPage)()+'</div>';
 const host=$('page-body'),context={getState:()=>state,mutate:persist,notify:toast,render,rerender:render,route,documentTemplates:()=>state.documentTemplates,documentCheck:documentsSatisfied};
 if(['agenda','clinica','hoje'].includes(route))mountClinic(host,context);
 if(['catalogo','orcamentos'].includes(route)||route==='paciente')mountOperations(host,context);
 if(route==='financeiro')mountFinance(host,context);
 if(route==='documentos'||route==='documento'||route==='paciente'&&tab==='documentos')mountDocuments(host,{...context,visitId:documentVisit||visitId});
 if(route==='ajustes')mountRecovery(host,{...context,onRestored:async()=>{for(const url of objectUrls.values())URL.revokeObjectURL(url);objectUrls.clear();state=await load();await render();}});
 if(route==='integracao')integrationHandle=mountIntegration(host,{config:{enabled:false}});
 try{if(route==='paciente'&&visit()){
  if(tab==='mapa'&&photo()){const url=await photoUrl(photo());if(seq!==renderSeq)return;fitLoadedMapPhoto($('map-photo'),url,seq);drawMap();}
  if(tab==='fotos'){for(const el of host.querySelectorAll('[data-photo-src]')){const p=visit().photos.find(p=>p.id===el.dataset.photoSrc);const url=await photoUrl(p);if(seq!==renderSeq)return;el.src=url;}if(seq!==renderSeq)return;const comparisonPatient=patientId;mountComparison($('comparison-panel'),{state,patientId:comparisonPatient,readPhoto:comparisonSource,selection:comparisonSelections.get(comparisonPatient)||state.comparisons?.filter(c=>c.patientId===comparisonPatient).at(-1),onSelection:value=>comparisonSelections.set(comparisonPatient,value),onSave:async value=>{await persist(s=>{s.comparisons??=[];s.comparisons.push({...value,id:uid(),patientId:comparisonPatient,savedAt:new Date().toISOString()});});toast('Composição salva neste navegador.');}});}
  lockCompletedVisit();
 }}catch(e){toast(e.message,true);}
}
function lockCompletedVisit(){if(!visit()||!['concluido'].includes(visit().status)&&!visit().lockedAt)return;document.querySelectorAll('#record-form input,#record-form textarea,#record-form button,#point-form input,#point-form select,#point-form textarea,#point-form button,#photo-upload,[data-action="photo-phase"],[data-action="undo-map"],[data-action="tool"]').forEach(el=>el.disabled=true);if($('map-instruction'))$('map-instruction').textContent='Consulta concluída. Marcações preservadas; correções por adendo na aba Registro.';}

function shapeSvg(p,color='#a58237'){if(p.kind==='ponto'||!Number.isFinite(p.x2)||!Number.isFinite(p.y2))return '';if(p.kind==='linha')return `<line x1="${p.x*1000}" y1="${p.y*1000}" x2="${p.x2*1000}" y2="${p.y2*1000}" stroke="${color}" stroke-width="3" vector-effect="non-scaling-stroke"/>`;const dx=p.x2-p.x,dy=p.y2-p.y,len=Math.hypot(dx,dy)||1,w=.055,nx=-dy/len*w,ny=dx/len*w;return `<path d="M${p.x*1000} ${p.y*1000}L${(p.x2+nx)*1000} ${(p.y2+ny)*1000}L${(p.x2-nx)*1000} ${(p.y2-ny)*1000}Z" fill="${color}33" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke"/>`;}
function drawMap(){if(!$('map-svg'))return;const doc=map(),points=[...doc.points,...(pending?[{...pending,id:'pending'}]:[])];$('map-svg').innerHTML=points.map(p=>shapeSvg(p,p.id==='pending'?'#ddad50':'#aa8537')).join('');$('map-markers').innerHTML=points.map((p,i)=>`<button type="button" class="map-marker ${p.id===selectedId?'selected':''} ${p.id==='pending'?'pending':''}" data-marker="${p.id}" style="left:${p.x*100}%;top:${p.y*100}%" aria-label="Marcação ${i+1}${p.region?': '+esc(p.region):''}">${p.id==='pending'?'+':i+1}</button>`).join('');$('point-count').textContent=doc.points.length;$('map-version').textContent=doc.version;$('point-list').innerHTML=doc.points.length?doc.points.map((p,i)=>`<button class="point-entry ${p.id===selectedId?'active':''}" data-action="select-point" data-id="${p.id}"><span class="number">${i+1}</span><span><strong>${esc(p.region)}</strong><small>${esc(p.product||'Produto não informado')}${p.quantity!==null?' · '+esc(p.quantity)+' '+p.unit:''}</small></span></button>`).join(''):'<div class="empty" style="padding:22px 17px;font-size:10px">Ainda sem marcações.<br>Toque no local desejado na foto.</div>';
  const totals=quantityTotals(doc.points);$('quantity-totals').textContent=Object.keys(totals).length?'Totais informados: '+Object.entries(totals).map(([u,n])=>`${n.toLocaleString('pt-BR')} ${u}`).join(' · '):'Quantidades não informadas.';
  $('delete-point').hidden=!selectedId;$('save-point').disabled=busy||!(selectedId||(pending&&(pending.kind==='ponto'||Number.isFinite(pending.x2))));
  const undo=document.querySelector('[data-action="undo-map"]');if(undo)undo.disabled=!doc.history.length;lockCompletedVisit();
}
function selectPoint(id){if(busy||importing)return;if(!clean())return;const p=map().points.find(p=>p.id===id);if(!p)return;selectedId=id;pending=null;for(const [id,key]of[['point-region','region'],['point-product','product'],['point-quantity','quantity'],['point-unit','unit'],['point-lot','lot'],['point-notes','notes']])$(id).value=p[key]??'';$('point-title').textContent='Editar marcação';$('point-state').textContent='Alteração manual';drawMap();}
function clearPoint(){selectedId=null;pending=null;dirty=false;if($('point-form')){$('point-form').reset();$('point-title').textContent='Nova marcação';$('point-state').textContent='Toque na fotografia';$('point-error').textContent='';$('map-instruction').textContent=tool==='ponto'?'Toque na foto para criar um ponto.':'Toque no início e no fim da marcação.';drawMap();}}
async function updateMap(mutator){const vId=visitId,pId=patientId,fId=photoId,rev=photo().revision;await persist(s=>{const v=s.visits.find(v=>v.id===vId&&v.patientId===pId),ph=v?.photos.find(p=>p.id===fId);assertVisitEditable(v);if(!ph||ph.revision!==rev)throw Error('A foto ou consulta foi alterada. Reabra o registro.');const old=v.maps[fId]||{version:0,points:[],history:[]};const next=mutator(structuredClone(old));v.maps[fId]={...next,version:old.version+1,history:[...old.history,old.points].slice(-20)};});}
function openDialog(title,fields,submit){if(busy||importing)return;const hadDraft=dirty||pending;if(!clean())return;if(hadDraft)void render();$('dialog-title').textContent=title;$('dialog-fields').innerHTML=fields;$('dialog-error').textContent='';dialogSubmit=submit;$('dialog-form').reset();delete $('dialog-form').dataset.unsaved;$('dialog').showModal();}
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="d-${name}">${label}</label><input id="d-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
function patientOptions(value){return `<div class="field"><label for="d-patient">Paciente</label><select id="d-patient" name="patientId">${state.patients.map(p=>`<option value="${p.id}" ${p.id===value?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>`;}
function appointmentDialog(id){const a=state.appointments.find(a=>a.id===id);if(!state.patients.length){toast('Cadastre uma paciente primeiro.');return;}openDialog(a?'Editar agendamento':'Novo agendamento',patientOptions(a?.patientId)+`<div class="field"><label for="d-professional">Profissional</label><select name="professionalId" id="d-professional">${professionalOptions(state,a?.professionalId)}</select></div><div class="field-grid">${field('Data','date',a?.date||agendaDate,'date','required')}${field('Horário','time',a?.time||'09:00','time','required')}${field('Duração (minutos)','duration',a?.duration||60,'number','min="5" max="480" required')}${field('Atendimento','service',a?.service||'','text','maxlength="120" required')}</div><div class="field"><label for="d-status">Situação</label><select id="d-status" name="status">${['agendado','confirmado','concluido','cancelado'].map(s=>`<option value="${s}" ${a?.status===s?'selected':''}>${{agendado:'A confirmar',confirmado:'Confirmado',concluido:'Atendido',cancelado:'Cancelado'}[s]}</option>`).join('')}</select></div>`,async f=>{const value={...a,id:a?.id||uid(),patientId:f.get('patientId'),professionalId:f.get('professionalId'),date:f.get('date'),time:f.get('time'),duration:Number(f.get('duration')),service:String(f.get('service')).trim(),status:f.get('status')};await persist(s=>scheduleClinicAppointment(s,value));});}
function newPatient(id){const p=state.patients.find(x=>x.id===id)||{};openDialog(id?'Editar cadastro de teste':'Nova paciente de teste',field('Nome fictício','name',p.name||'','text','maxlength="140" required minlength="2"')+field('Telefone de teste (opcional)','phone',p.phone||'','tel','maxlength="25"')+field('E-mail (opcional)','email',p.email||'','email','maxlength="254"')+field('CPF de teste (opcional)','cpf',p.cpf||'','text','maxlength="14"')+field('Nascimento (opcional)','birthDate',p.birthDate||'','date')+'<p class="small-label">Use somente dados fictícios nesta demonstração.</p>',async f=>{await persist(s=>savePatient(s,{...p,id:p.id||uid(),...Object.fromEntries(f)}));});}
function scheduleRequest(id){const r=state.requests.find(r=>r.id===id&&r.status==='pendente');if(!r)throw Error('Solicitação indisponível.');openDialog('Confirmar solicitação de teste',`<p class="subtitle">${esc(r.name)} · ${esc(r.phone)}</p><div class="field"><label for="d-match">Paciente — confira a identidade</label><select id="d-match" name="match"><option value="new">Novo cadastro com dados do pedido</option>${state.patients.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.phone)}</option>`).join('')}</select></div><div class="field"><label for="d-professional">Profissional</label><select id="d-professional" name="professionalId">${professionalOptions(state)}</select></div><div class="field-grid">${field('Dia confirmado','date',r.date,'date','required')}${field('Horário confirmado','time','14:00','time','required')}${field('Duração (minutos)','duration',60,'number','required min="5" max="480"')}${field('Atendimento','service',r.interest,'text','required maxlength="120"')}</div>`,async f=>{const match=f.get('match'),appointment={id:uid(),professionalId:f.get('professionalId'),date:f.get('date'),time:f.get('time'),duration:Number(f.get('duration')),service:String(f.get('service')).trim(),status:'confirmado'};await persist(s=>confirmSiteRequest(s,{requestId:id,patientId:match==='new'?undefined:match,newPatient:match==='new'?{id:uid(),name:r.name,phone:r.phone}:undefined,appointment}));agendaDate=appointment.date;});}
async function attend(id){const a=state.appointments.find(a=>a.id===id);if(!a||a.status==='cancelado')throw Error('Agendamento indisponível.');let v=state.visits.find(v=>v.appointmentId===id);if(!v){v={id:uid(),patientId:a.patientId,appointmentId:a.id,professionalId:a.professionalId,date:a.date,service:a.service,notes:'',status:'rascunho',photos:[],maps:{}};await persist(s=>s.visits.push(v));}navigate(`paciente/${v.patientId}/${v.id}/registro`);}
function newVisit(){openDialog('Nova consulta de teste',field('Atendimento','service','','text','required maxlength="120"')+field('Data','date',dateKey(),'date','required'),async f=>{const v={id:uid(),patientId,date:f.get('date'),service:String(f.get('service')).trim(),notes:'',status:'rascunho',photos:[],maps:{}};await persist(s=>s.visits.push(v));setTimeout(()=>navigate(`paciente/${patientId}/${v.id}/registro`),0);});}
function billDialog(){openDialog('Nova cobrança de teste',patientOptions(patientId)+field('Descrição','description','','text','required maxlength="120"')+`<div class="field-grid">${field('Valor cobrado (R$)','total','','text','inputmode="decimal" required')}${field('Custo variável (R$)','cost','0,00','text','inputmode="decimal" required')}</div>`,async f=>{const b={id:uid(),patientId:f.get('patientId'),description:String(f.get('description')).trim(),date:dateKey(),total:cents(f.get('total')),cost:cents(f.get('cost'))};if(!b.total)throw Error('Informe um valor maior que zero.');await persist(s=>{if(!s.patients.some(p=>p.id===b.patientId)||!b.description)throw Error('Confira a paciente e a descrição.');s.bills.push(b);});});}
function receiveDialog(id){const b=state.bills.find(b=>b.id===id),balance=billBalance(b,state.payments),operationId=uid();openDialog('Registrar recebimento',`<p class="subtitle" style="margin-bottom:18px">${esc(patient(b.patientId)?.name)} · Saldo ${money(balance)}</p>`+field('Valor recebido (R$)','amount',(balance/100).toFixed(2).replace('.',','),'text','inputmode="decimal" required')+'<div class="field"><label for="d-method">Forma de recebimento</label><select id="d-method" name="method"><option>Pix</option><option>Dinheiro</option><option>Cartão</option></select></div>',async f=>{const p={id:uid(),operationId,billId:id,amount:cents(f.get('amount')),date:dateKey(),method:f.get('method')};await persist(s=>{paymentCheck(p,s);s.payments.push(p);});});}
async function ingest(file){if(!file)return;if(!visit())throw Error('Abra uma consulta antes de adicionar fotos.');assertVisitEditable(visit());if(!clean())return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('Use uma foto JPEG, PNG ou WebP de até 8 MB.');const vId=visitId,pId=patientId,photoNumber=visit().photos.length+1;if(importing)throw Error('Aguarde a foto anterior.');importing=true;let bitmap;try{bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});if(bitmap.width*bitmap.height>40000000)throw Error('Imagem grande demais. Utilize uma foto com até 40 megapixels.');const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d',{alpha:false});ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const preview=await new Promise(r=>canvas.toBlob(r,'image/webp',.92));if(!preview)throw Error('Não foi possível preparar a foto.');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join('');const meta={id:uid(),label:'Foto '+photoNumber+' · teste',phase:'registro',revision:hash,width:canvas.width,height:canvas.height,sha256:hash};await persist(s=>{const v=s.visits.find(v=>v.id===vId&&v.patientId===pId);assertVisitEditable(v);if(v.photos.some(p=>p.sha256===hash))throw Error('Esta mesma fotografia já está na consulta. Abra a foto existente.');v.photos.push(meta);v.maps[meta.id]={version:0,points:[],history:[]};},{id:meta.id,original:file,preview});photoId=meta.id;toast('Foto de teste salva neste navegador. O original foi preservado.');await render();}finally{bitmap?.close();importing=false;}}
async function exportMap(){if(dirty||pending)throw Error('Salve ou cancele a edição antes de exportar.');const p=photo(),doc=map(),img=$('map-photo');if(!p||!img.complete)throw Error('Aguarde a fotografia.');const w=img.naturalWidth,h=img.naturalHeight,footer=110+doc.points.length*38,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h+footer;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h+footer);ctx.drawImage(img,0,0,w,h);for(const [i,p] of doc.points.entries()){const x=p.x*w,y=p.y*h;ctx.strokeStyle='#997632';ctx.fillStyle='#99763233';ctx.lineWidth=Math.max(2,w*.003);if(p.kind==='linha'){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(p.x2*w,p.y2*h);ctx.stroke();}if(p.kind==='leque'){const dx=p.x2-p.x,dy=p.y2-p.y,len=Math.hypot(dx,dy)||1,nx=-dy/len*.055,ny=dx/len*.055;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo((p.x2+nx)*w,(p.y2+ny)*h);ctx.lineTo((p.x2-nx)*w,(p.y2-ny)*h);ctx.closePath();ctx.fill();ctx.stroke();}ctx.beginPath();ctx.arc(x,y,w*.019,0,Math.PI*2);ctx.fillStyle='#997632';ctx.fill();ctx.strokeStyle='#fff';ctx.stroke();ctx.fillStyle='#fff';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`600 ${w*.022}px sans-serif`;ctx.fillText(i+1,x,y);}ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillStyle='#514c3b';ctx.font=`600 ${w*.021}px sans-serif`;ctx.fillText('Ana Maria Jacob · PILOTO LOCAL / SEM VALIDADE DE PRONTUÁRIO',25,h+34);ctx.font=`${w*.017}px sans-serif`;ctx.fillText(`Registro manual · ${visit().date} · versão ${doc.version} · ${p.label}`,25,h+65);doc.points.forEach((p,i)=>ctx.fillText(`${i+1}. ${p.region} · ${p.product||'produto não informado'}${p.quantity!==null?' · '+p.quantity+' '+p.unit:''}${p.lot?' · lote '+p.lot:''}`,25,h+100+i*38,w-50));const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));download(blob,'mapa-teste-ana-maria-jacob.png');toast('Imagem de teste exportada com a legenda.');}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
document.addEventListener('click',async e=>{const a=e.target.closest('a[href^="#"]');if(a){e.preventDefault();if(a.getAttribute('href')==='#content'){document.getElementById('content').focus();return;}navigate(a.getAttribute('href').slice(1));return;}if(busy||importing){toast('Aguarde o registro em andamento.');return;}const marker=e.target.closest('[data-marker]');if(marker){if(marker.dataset.marker!=='pending'&&!drag?.moved)selectPoint(marker.dataset.marker);return;}const button=e.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;try{if(action==='new-appointment')appointmentDialog();else if(action==='edit-appointment')appointmentDialog(id);else if(action==='new-patient')newPatient();else if(action==='edit-patient')newPatient(id);else if(action==='attend')await attend(id);else if(action==='new-visit')newVisit();else if(action==='new-bill')billDialog();else if(action==='receive')receiveDialog(id);else if(action==='today'){if(!clean())return;agendaDate=dateKey();await render();}else if(action==='select-point')selectPoint(id);else if(action==='cancel-point')clearPoint();else if(action==='tool'){if(!clean())return;clearPoint();tool=id;document.querySelectorAll('[data-action="tool"]').forEach(b=>{b.classList.toggle('active',b.dataset.id===tool);b.setAttribute('aria-pressed',b.dataset.id===tool);});$('map-instruction').textContent=tool==='ponto'?'Toque na foto para criar um ponto.':'Toque no início e no fim da marcação.';}else if(action==='zoom-in'||action==='zoom-out'){zoom=Math.max(1,Math.min(3,zoom+(action==='zoom-in'?.5:-.5)));fitMapPlane();}else if(action==='toggle-markers'){const hidden=$('photo-stage').classList.toggle('no-markers');button.textContent=hidden?'Mostrar marcações':'Ocultar marcações';}else if(action==='delete-point'){const deletedId=selectedId;if(!deletedId)return;await updateMap(doc=>({...doc,points:doc.points.filter(p=>p.id!==deletedId)}));clearPoint();toast('Marcação removida do piloto. Você pode desfazer.');}else if(action==='undo-map'){if(!clean())return;const vId=visitId,fId=photoId;await persist(s=>{const v=s.visits.find(v=>v.id===vId);assertVisitEditable(v);const doc=v.maps[fId];if(!doc.history.length)throw Error('Nada para desfazer.');doc.points=doc.history.pop();doc.version++;});clearPoint();toast('Última alteração desfeita no piloto.');}else if(action==='open-photo-map'){photoId=id;navigate(`paciente/${patientId}/${visitId}/mapa`);}else if(action==='photo-phase'){const p=visit().photos.find(p=>p.id===id),vId=visitId;openDialog('Classificar fotografia',field('Nome da foto','label',p.label,'text','required maxlength="100"')+`<div class="field"><label for="d-phase">Momento</label><select id="d-phase" name="phase">${['registro','antes','depois'].map(x=>`<option value="${x}" ${p.phase===x?'selected':''}>${x}</option>`).join('')}</select></div>`,async f=>{await persist(s=>{const v=s.visits.find(v=>v.id===vId);assertVisitEditable(v);const ph=v.photos.find(p=>p.id===id);ph.label=String(f.get('label')).trim();ph.phase=f.get('phase');});});}else if(action==='export-map')await exportMap();}catch(error){toast(error.message,true);}});
document.addEventListener('click',e=>{const plane=e.target.closest('#photo-plane');if(busy||importing||visit()?.status==='concluido'||visit()?.lockedAt||!plane||e.target.closest('[data-marker]')||drag?.moved)return;if(selectedId||dirty){if(!clean())return;clearPoint();}if(!$('map-photo')?.complete||!$('map-photo').naturalWidth)return;const rect=plane.getBoundingClientRect(),at=normalizedPoint(e.clientX,e.clientY,rect);if(tool!=='ponto'&&!pending){pending={id:'pending',kind:tool,...at};$('map-instruction').textContent='Agora toque no ponto final da linha ou leque.';drawMap();$('save-point').disabled=true;return;}if(tool!=='ponto'&&pending&&pending.x2===undefined){pending={...pending,x2:at.x,y2:at.y};}else pending={id:'pending',kind:tool,...at};dirty=true;drawMap();$('point-state').textContent='Ainda não salva';if(e.detail===0||!window.matchMedia('(max-width: 620px), (pointer: coarse)').matches)$('point-region').focus();});
document.addEventListener('pointerdown',e=>{const marker=e.target.closest('[data-marker]');if(busy||importing||visit()?.status==='concluido'||visit()?.lockedAt||!marker||marker.dataset.marker==='pending')return;if(dirty||pending)return;const p=map().points.find(p=>p.id===marker.dataset.marker);drag={id:p.id,startX:e.clientX,startY:e.clientY,moved:false,marker,original:structuredClone(p)};marker.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<5&&!drag.moved)return;drag.moved=true;const at=normalizedPoint(e.clientX,e.clientY,$('photo-plane').getBoundingClientRect());drag.next=at;const bounded=translateAnnotation(drag.original,at);drag.marker.style.left=bounded.x*100+'%';drag.marker.style.top=bounded.y*100+'%';});
document.addEventListener('pointerup',async()=>{if(!drag)return;const d=drag;if(d.moved){try{await updateMap(doc=>({...doc,points:doc.points.map(p=>{if(p.id!==d.id)return p;return translateAnnotation(p,d.next);})}));drawMap();toast('Posição salva no piloto.');}catch(e){drawMap();toast(e.message,true);}}setTimeout(()=>{drag=null;},0);});
document.addEventListener('pointercancel',()=>{drag=null;drawMap();});
document.addEventListener('input',e=>{if(e.target.closest('#dialog-form'))$('dialog-form').dataset.unsaved='true';if(e.target.id==='patient-search')$('patient-grid').innerHTML=patientCards(e.target.value);if(e.target.closest('#point-form')){editGeneration++;dirty=true;$('point-state').textContent='Edição não salva';}if(e.target.id==='visit-notes'){editGeneration++;dirty=true;}});
document.addEventListener('change',async e=>{try{if(busy||importing){if(e.target.id==='photo-select')e.target.value=photoId;if(e.target.id==='agenda-date')e.target.value=agendaDate;toast('Aguarde o registro em andamento.');return;}if(e.target.id==='agenda-date'){if(!clean()){e.target.value=agendaDate;return;}agendaDate=e.target.value;await render();}if(e.target.id==='photo-select'){if(!clean()){e.target.value=photoId;return;}photoId=e.target.value;selectedId=null;pending=null;zoom=1;await render();}if(e.target.id==='photo-upload')await ingest(e.target.files[0]);}catch(error){toast(error.message,true);}});
document.addEventListener('submit',async e=>{
  if(!['point-form','record-form'].includes(e.target.id))return;
  e.preventDefault();if(busy||importing){toast('Aguarde o registro em andamento.');return;}
  if(e.target.id==='point-form'){
    try{
      const editingId=selectedId, generation=editGeneration;
      const base=editingId?map().points.find(p=>p.id===editingId):pending;
      if(!base||base.kind!=='ponto'&&base.x2===undefined)throw Error('Marque a posição na foto primeiro.');
      const q=$('point-quantity').value.trim().replace(',','.');
      if(q&&!/^\d+(\.\d{1,4})?$/.test(q))throw Error('Confira a quantidade informada.');
      const savedPoint=annotationCheck({...base,id:editingId||uid(),region:$('point-region').value.trim(),product:$('point-product').value.trim(),quantity:q?Number(q):null,unit:$('point-unit').value,lot:$('point-lot').value.trim(),notes:$('point-notes').value.trim()});
      $('save-point').disabled=true;
      await updateMap(doc=>({...doc,points:editingId?doc.points.map(x=>x.id===editingId?savedPoint:x):[...doc.points,savedPoint]}));
      if(editGeneration===generation){clearPoint();toast('Marcação salva neste navegador.');}
      else{selectedId=savedPoint.id;pending=null;dirty=true;drawMap();$('point-title').textContent='Editar marcação';$('point-state').textContent='Há alterações ainda não salvas';toast('Versão anterior salva. Salve as alterações mais recentes.');}
    }catch(error){$('point-error').textContent=error.message;$('save-point').disabled=false;}
  }else{
    try{
      const id=visitId,notes=$('visit-notes').value.trim(),generation=editGeneration;
      await persist(s=>{const v=s.visits.find(v=>v.id===id);assertVisitEditable(v);v.notes=notes;});
      dirty=editGeneration!==generation||$('visit-notes').value.trim()!==notes;
      $('record-saved').textContent=dirty?' Versão anterior salva. Há alterações pendentes.':' Rascunho local salvo.';
      toast(dirty?'Versão anterior salva. Salve as alterações mais recentes.':'Rascunho salvo no piloto.');
    }catch(error){toast(error.message,true);}
  }
});
$('dialog-form').addEventListener('submit',async e=>{e.preventDefault();if(busy||importing)return;const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await dialogSubmit(new FormData(e.target));delete e.target.dataset.unsaved;$('dialog').close();toast('Registro salvo no piloto local.');await render();}catch(error){$('dialog-error').textContent=error.message;}finally{b.disabled=false;}});
function discardNativeDialog(){if(busy||importing)return false;if($('dialog-form').dataset.unsaved&&!confirm('Há alterações não salvas no formulário. Descartar?'))return false;delete $('dialog-form').dataset.unsaved;return true;}
$('close-dialog').onclick=$('cancel-dialog').onclick=()=>{if(discardNativeDialog())$('dialog').close();};
$('dialog').addEventListener('cancel',e=>{if(!discardNativeDialog())e.preventDefault();});
window.addEventListener('hashchange',()=>{void setHash().catch(error=>toast(error.message,true));});window.addEventListener('beforeunload',e=>{if(dirty||pending||busy||importing||integrationHandle?.isDirty()||integrationHandle?.isBusy()||document.querySelector('form[data-unsaved]')){e.preventDefault();e.returnValue='';}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="schedule-request"]');if(b)try{scheduleRequest(b.dataset.id);}catch(error){toast(error.message,true);}});
document.addEventListener('visibilitychange',async()=>{if(document.visibilityState!=='visible'||integrationHandle?.isDirty()||integrationHandle?.isBusy()||dirty||pending||document.querySelector('form[data-unsaved]')||busy||importing||document.querySelector('dialog[open]')||!state)return;const previousRevision=state.revision,previousRender=renderSeq;try{const latest=await load();if(integrationHandle?.isDirty()||integrationHandle?.isBusy()||dirty||pending||document.querySelector('form[data-unsaved]')||busy||importing||document.querySelector('dialog[open]')||state.revision!==previousRevision||renderSeq!==previousRender)return;if(latest.revision!==state.revision){state=latest;await render();}}catch(error){toast(error.message,true);}});
$('area-switch').addEventListener('change',e=>{navigate(e.target.value);e.target.value=route==='paciente'?'pacientes':route;});
$('date-label').textContent=new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'});
window.addEventListener('resize',()=>fitMapPlane());
try{await setHash();}catch(e){$('content').innerHTML='<div class="card card-body"><h1>O piloto não abriu.</h1><p>O armazenamento local deste navegador está indisponível. Tente uma janela comum.</p></div>';toast(e.message,true);}
